		button.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(primary ? new Color(184, 132, 36) : new Color(82, 87, 93)),
			BorderFactory.createEmptyBorder(6, 8, 6, 8)));
	}

	private static void styleCompactButton(JButton button, Color foreground)
	{
		button.setFocusPainted(false);
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		button.setForeground(foreground);
		button.setBackground(CARD_ALT);
		button.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(DIVIDER),
			BorderFactory.createEmptyBorder(4, 7, 4, 7)));
	}

	private static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private static String html(String body)
	{
		return "<html><div style='width:158px; line-height:1.2'>" + body + "</div></html>";
	}

	private static final class WidthTrackingPanel extends JPanel implements Scrollable
	{
		@Override public Dimension getPreferredScrollableViewportSize() { return getPreferredSize(); }
		@Override public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction) { return 16; }
		@Override public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction) { return Math.max(16, visible.height - 16); }
		@Override public boolean getScrollableTracksViewportWidth() { return true; }
		@Override public boolean getScrollableTracksViewportHeight() { return false; }
	}
}

package com.itemsource;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import net.runelite.api.Quest;

final class ItemSourceParser
{
	private static final Pattern HEADING = Pattern.compile("(?is)<h[2-6][^>]*>(.*?)</h[2-6]>");
	private static final Pattern TABLE = Pattern.compile("(?is)<table[^>]*>(.*?)</table>");
	private static final Pattern ROW = Pattern.compile("(?is)<tr[^>]*>(.*?)</tr>");
	private static final Pattern CELL = Pattern.compile("(?is)<(th|td)[^>]*>(.*?)</\\1>");
	private static final Pattern TAG = Pattern.compile("(?is)<[^>]+>");
	private static final Pattern HIDDEN = Pattern.compile("(?is)<(script|style|sup)[^>]*>.*?</\\1>");
	private static final Pattern FRACTION = Pattern.compile("^(\\d+(?:\\.\\d+)?)/(\\d+(?:\\.\\d+)?)$");
	private static final Pattern LINK_TITLE = Pattern.compile("(?is)<a[^>]*\\btitle=\"([^\"]+)\"");
	private static final String CELL_META = "\u001f";

	ItemSourceResult parse(String title, String html)
	{
		Map<SourceCategory, Set<SourceEntry>> found = new EnumMap<>(SourceCategory.class);
		for (SourceCategory category : SourceCategory.values()) found.put(category, new LinkedHashSet<>());
		List<Heading> headings = headings(html);
		for (int index = 0; index < headings.size(); index++)
		{
			Heading heading = headings.get(index);
			SourceCategory category = categoryFor(heading.text);
			if (category == null) continue;
			int end = index + 1 < headings.size() ? headings.get(index + 1).start : html.length();
			found.get(category).addAll(entries(category, html.substring(heading.end, end)));
		}
		Map<SourceCategory, List<SourceEntry>> sources = new EnumMap<>(SourceCategory.class);
		found.forEach((category, entries) -> {
			if (!entries.isEmpty()) sources.put(category, new ArrayList<>(entries));
		});
		return new ItemSourceResult(title,
			"https://oldschool.runescape.wiki/w/" + title.replace(' ', '_'), sources);
	}

	private static List<SourceEntry> entries(SourceCategory category, String section)
	{
		List<SourceEntry> entries = new ArrayList<>();
		for (List<List<String>> table : tables(section))
		{
			if (entries.size() >= 12) break;
			switch (category)
			{
				case MONSTER_DROPS: addDrops(entries, table); break;
				case SHOPS: addShops(entries, table); break;
				case GROUND_SPAWNS: addSpawns(entries, table); break;
				case CRAFTING_AND_SKILLS: addCreation(entries, table); break;
				case REWARDS: addRewards(entries, table); break;
				default: break;
			}
		}
		return entries.size() > 12 ? entries.subList(0, 12) : entries;
	}

	private static void addDrops(List<SourceEntry> output, List<List<String>> rows)
	{
		if (rows.size() < 2) return;
		int source = column(rows.get(0), "source");
		int rarity = column(rows.get(0), "rarity");
		if (source < 0 || rarity < 0) return;
		for (int i = 1; i < rows.size() && output.size() < 12; i++)
		{
			String displayedName = value(rows.get(i), source);
			String linkedPage = pageValue(rows.get(i), source);
			String name = linkedPage.isEmpty() ? displayedName : linkedPage;
			String rate = value(rows.get(i), rarity);
			String variant = displayedName.equalsIgnoreCase(name) ? "" : displayedName.substring(
				Math.min(displayedName.length(), name.length())).trim();
			if (!name.isEmpty()) output.add(new SourceEntry(name,
				(variant.isEmpty() ? "" : variant + " · ")
					+ (rate.isEmpty() ? "Drop rate unavailable" : "Drop rate: " + normalizeRate(rate)),
				null, 0, requiredQuests(rows.get(i))));
		}
	}

	private static void addShops(List<SourceEntry> output, List<List<String>> rows)
	{
		if (rows.size() < 2) return;
		List<String> headers = rows.get(0);
		int seller = column(headers, "seller");
		int location = column(headers, "location");
		int stock = column(headers, "number in stock");
		int price = column(headers, "price sold at");
		for (int i = 1; i < rows.size() && output.size() < 12; i++)
		{
			String name = pageValue(rows.get(i), seller);
			if (name.isEmpty()) name = value(rows.get(i), seller);
			if (name.isEmpty()) continue;
			String stockValue = value(rows.get(i), stock);
			List<String> details = new ArrayList<>();
			addDetail(details, value(rows.get(i), location));
			addLabeled(details, "Price", value(rows.get(i), price), " gp");
			addLabeled(details, "Stock", stockValue, "");
			output.add(new SourceEntry(name, String.join(" · ", details), null, 0,
				requiredQuests(rows.get(i)), null,
				"0".equals(stockValue.replace(",", "").trim()) ? "No stock in this shop state" : null));
		}
	}

	private static void addSpawns(List<SourceEntry> output, List<List<String>> rows)
	{
		if (rows.size() < 2) return;
		int location = column(rows.get(0), "location");
		int count = column(rows.get(0), "spawns");
		for (int i = 1; i < rows.size() && output.size() < 12; i++)
		{
			String place = value(rows.get(i), location);
			if (!place.isEmpty()) output.add(new SourceEntry(place,
				value(rows.get(i), count).isEmpty() ? "Ground spawn" : "Spawns: " + value(rows.get(i), count),
				null, 0, requiredQuests(rows.get(i))));
		}
	}

	private static void addCreation(List<SourceEntry> output, List<List<String>> rows)
	{
		if (rows.size() < 2 || output.size() >= 12) return;
		for (int i = 0; i < rows.size() - 1; i++)
		{
			List<String> header = rows.get(i);
			if (column(header, "skill") < 0 || column(header, "level") < 0) continue;
			List<String> values = rows.get(i + 1);
			String skill = value(values, column(header, "skill"));
			if (skill.isEmpty()) continue;
			List<String> details = new ArrayList<>();
			String levelText = value(values, column(header, "level")).replace("(b)", "").trim();
			addLabeled(details, "Level", levelText, "");
			addLabeled(details, "XP", value(values, column(header, "xp")), "");
			String facility = findValueAfter(rows, "facilities");
			addDetail(details, facility);
			String ingredient = findIngredient(rows);
			addDetail(details, ingredient);
			List<String> questRequirements = new ArrayList<>();
			for (List<String> row : rows)
			{
				for (String quest : requiredQuests(row))
				{
					if (!questRequirements.contains(quest)) questRequirements.add(quest);
				}
			}
			output.add(new SourceEntry(skill, String.join(" · ", details), skill,
				leadingNumber(levelText), questRequirements));
			return;
		}
	}

	private static void addRewards(List<SourceEntry> output, List<List<String>> rows)
	{
		if (rows.size() < 2) return;
		for (int i = 1; i < rows.size() && output.size() < 12; i++)
		{
			List<String> row = rows.get(i);
			if (row.isEmpty()) continue;
			String title = clueTierName(value(row, 0));
			List<String> detailCells = new ArrayList<>();
			for (int cell = 1; cell < Math.min(row.size(), 3); cell++) detailCells.add(value(row, cell));
			String detail = detailCells.isEmpty() ? "Reward source" : String.join(" · ", detailCells);
			if (!title.isEmpty()) output.add(new SourceEntry(title, detail, null, 0,
				requiredQuests(row)));
		}
	}

	private static List<String> requiredQuests(List<String> row)
	{
		List<String> found = new ArrayList<>();
		for (String rawCell : row)
		{
			String cell = visible(rawCell);
			String text = normalizeForMatch(cell);
			Quest longest = null;
			for (Quest quest : Quest.values())
			{
				String questName = normalizeForMatch(quest.getName());
				if (containsPhrase(text, questName)
					&& (longest == null || questName.length() > normalizeForMatch(longest.getName()).length()))
				{
					longest = quest;
				}
			}
			if (longest != null && !found.contains(longest.getName())) found.add(longest.getName());
		}
		return found;
	}

	private static boolean containsPhrase(String text, String phrase)
	{
		int index = text.indexOf(phrase);
		if (index < 0) return false;
		int end = index + phrase.length();
		return (index == 0 || text.charAt(index - 1) == ' ')
			&& (end == text.length() || text.charAt(end) == ' ');
	}

	private static String normalizeForMatch(String value)
	{
		return value.toLowerCase(Locale.ENGLISH)
			.replace('’', '\'').replaceAll("[^a-z0-9']+", " ").trim();
	}

	private static String normalizeRate(String rate)
	{
		Matcher matcher = FRACTION.matcher(rate.replace(",", "").trim());
		if (!matcher.matches()) return rate;
		double numerator = Double.parseDouble(matcher.group(1));
		double denominator = Double.parseDouble(matcher.group(2));
		if (numerator <= 0 || denominator <= 0) return rate;
		double oneIn = denominator / numerator;
		DecimalFormat format = new DecimalFormat("0.##", DecimalFormatSymbols.getInstance(Locale.ENGLISH));
		return "1/" + format.format(oneIn);
	}

	private static String findValueAfter(List<List<String>> rows, String label)
	{
		for (List<String> row : rows)
		{
			int index = column(row, label);
			if (index >= 0 && index + 1 < row.size()) return value(row, index + 1);
		}
		return "";
	}

	private static String findIngredient(List<List<String>> rows)
	{
		for (int i = 0; i < rows.size() - 1; i++)
		{
			int item = column(rows.get(i), "item");
			int quantity = column(rows.get(i), "quantity");
			if (item < 0 || quantity < 0) continue;
			List<String> row = rows.get(i + 1);
			String name = value(row, item);
			String count = value(row, quantity);
			if (name.isEmpty() && item + 2 < row.size())
			{
				name = value(row, item + 1);
				count = value(row, item + 2);
			}
			if (!name.isEmpty()) return "Requires: " + (count.isEmpty() ? "" : count + " × ") + name;
		}
		return "";
	}

	private static List<List<List<String>>> tables(String section)
	{
		List<List<List<String>>> result = new ArrayList<>();
		Matcher tableMatcher = TABLE.matcher(section);
		while (tableMatcher.find())
		{
			List<List<String>> rows = new ArrayList<>();
			Matcher rowMatcher = ROW.matcher(tableMatcher.group(1));
			while (rowMatcher.find())
			{
				List<String> cells = new ArrayList<>();
				Matcher cellMatcher = CELL.matcher(rowMatcher.group(1));
				while (cellMatcher.find())
				{
					String raw = cellMatcher.group(2);
					Matcher link = LINK_TITLE.matcher(raw);
					String page = link.find() ? decode(link.group(1)) : "";
					cells.add(clean(raw) + CELL_META + page);
				}
				if (!cells.isEmpty()) rows.add(cells);
			}
			if (!rows.isEmpty()) result.add(rows);
		}
		return result;
	}

	private static List<Heading> headings(String html)
	{
		List<Heading> result = new ArrayList<>();
		Matcher matcher = HEADING.matcher(html);
		while (matcher.find()) result.add(new Heading(clean(matcher.group(1)), matcher.start(), matcher.end()));
		return result;
	}

	private static SourceCategory categoryFor(String value)
	{
		String heading = value.toLowerCase(Locale.ENGLISH);
		if (heading.contains("shop") || heading.contains("store location")) return SourceCategory.SHOPS;
		if (heading.equals("item sources") || heading.contains("drop source") || heading.contains("monster drop")) return SourceCategory.MONSTER_DROPS;
		if (heading.equals("creation") || heading.contains("creating") || heading.contains("crafting") || heading.contains("harvesting")) return SourceCategory.CRAFTING_AND_SKILLS;
		if (heading.contains("spawn location") || heading.contains("item spawn") || heading.equals("spawns")) return SourceCategory.GROUND_SPAWNS;
		if (heading.contains("reward") || heading.contains("treasure trail")) return SourceCategory.REWARDS;
		return null;
	}

	private static int column(List<String> cells, String wanted)
	{
		for (int i = 0; i < cells.size(); i++) if (visible(cells.get(i)).toLowerCase(Locale.ENGLISH).equals(wanted)) return i;
		return -1;
	}

	private static String value(List<String> row, int index) { return index >= 0 && index < row.size() ? visible(row.get(index)) : ""; }
	private static String pageValue(List<String> row, int index)
	{
		if (index < 0 || index >= row.size()) return "";
		String cell = row.get(index);
		int split = cell.indexOf(CELL_META);
		return split < 0 ? "" : cell.substring(split + CELL_META.length());
	}
	private static String visible(String cell)
	{
		int split = cell.indexOf(CELL_META);
		return split < 0 ? cell : cell.substring(0, split);
	}
	private static void addDetail(List<String> details, String value) { if (!value.isEmpty()) details.add(value); }
	private static void addLabeled(List<String> details, String label, String value, String suffix) { if (!value.isEmpty()) details.add(label + ": " + value + suffix); }
	private static int leadingNumber(String value)
	{
		Matcher matcher = Pattern.compile("^(\\d+)").matcher(value);
		return matcher.find() ? Integer.parseInt(matcher.group(1)) : 0;
	}

	private static String clean(String html)
	{
		return decode(TAG.matcher(HIDDEN.matcher(html).replaceAll(" ")).replaceAll(" "))
			.replaceAll("\\s+", " ").trim();
	}

	private static String decode(String value)
	{
		return value.replace("&amp;", "&").replace("&quot;", "\"").replace("&#39;", "'")
			.replace("&lt;", "<").replace("&gt;", ">").replace("&nbsp;", " ")
			.replace("&#160;", " ").replace("&apos;", "'");
	}

	private static String clueTierName(String value)
	{
		switch (value.toLowerCase(Locale.ENGLISH))
		{
			case "beginner": case "easy": case "medium": case "hard": case "elite": case "master":
				return value + " clue scroll";
			default: return value;
		}
	}

	private static final class Heading
	{
		private final String text; private final int start; private final int end;
		private Heading(String text, int start, int end) { this.text = text; this.start = start; this.end = end; }
	}
}

package com.itemsource;

import javax.inject.Inject;
import javax.swing.SwingUtilities;
import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "ItemSource",
	internalName = "itemsource",
	description = "Find shops, drops, crafting methods, spawns, and rewards for OSRS items",
	tags = {"items", "wiki", "ironman", "shops", "drops", "crafting", "spawns", "rewards"}
)
public class ItemSourcePlugin extends Plugin
{
	@Inject private Client client;
	@Inject private ClientToolbar toolbar;
	@Inject private ItemManager itemManager;
	@Inject private ItemSourcePanel panel;
	private NavigationButton navigation;

	@Provides
	ItemSourceConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ItemSourceConfig.class);
	}

	@Override protected void startUp()
	{
		SwingUtilities.invokeLater(() -> { navigation = NavigationButton.builder().tooltip("ItemSource")
			.icon(ImageUtil.loadImageResource(ItemSourcePlugin.class, "/icon.png"))
			.priority(7).panel(panel).build(); toolbar.addNavigation(navigation); });
		log.debug("ItemSource started");
	}

	@Override protected void shutDown()
	{
		panel.deactivate();
		SwingUtilities.invokeLater(() -> { if (navigation != null) { toolbar.removeNavigation(navigation); navigation = null; } });
		log.debug("ItemSource stopped");
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!"Examine".equals(event.getOption()) || event.getItemId() < 0) return;
		String itemName = itemManager.getItemComposition(event.getItemId()).getName();
		if (itemName == null || itemName.isEmpty() || "null".equals(itemName)) return;
		client.getMenu().createMenuEntry(-1)
			.setOption("Search in ItemSource")
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(entry -> SwingUtilities.invokeLater(() ->
			{
				toolbar.openPanel(navigation);
				panel.searchFor(itemName);
			}));
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ItemSourceConfig.GROUP.equals(event.getGroup()))
		{
			SwingUtilities.invokeLater(panel::refreshCurrent);
		}
	}

}

package com.itemsource;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Locale;

final class ItemSourceResult
{
	private final String itemName;
	private final String wikiUrl;
	private final Map<SourceCategory, List<SourceEntry>> sources;

	ItemSourceResult(String itemName, String wikiUrl, Map<SourceCategory, List<SourceEntry>> sources)
	{
		this.itemName = itemName;
		this.wikiUrl = wikiUrl;
		EnumMap<SourceCategory, List<SourceEntry>> copy = new EnumMap<>(SourceCategory.class);
		sources.forEach((key, value) -> copy.put(key,
			Collections.unmodifiableList(new ArrayList<>(value))));
		this.sources = Collections.unmodifiableMap(copy);
	}

	String getItemName() { return itemName; }
	String getWikiUrl() { return wikiUrl; }
	Map<SourceCategory, List<SourceEntry>> getSources() { return sources; }
	boolean hasSources() { return sources.values().stream().anyMatch(v -> !v.isEmpty()); }

	ItemSourceResult withRequirements(Map<String, SourceRequirement> requirements)
	{
		Map<SourceCategory, List<SourceEntry>> enriched = new EnumMap<>(SourceCategory.class);
		for (Map.Entry<SourceCategory, List<SourceEntry>> category : sources.entrySet())
		{
			List<SourceEntry> entries = new ArrayList<>();
			for (SourceEntry entry : category.getValue())
			{
				SourceRequirement requirement = requirements.get(requirementKey(entry.getTitle()));
				entries.add(requirement == null ? entry : entry.withRequirement(requirement));
			}
			enriched.put(category.getKey(), entries);
		}
		return new ItemSourceResult(itemName, wikiUrl, enriched);
	}

	static String requirementKey(String title)
	{
		return title.replaceFirst("\\s*\\([^)]*\\)\\s*$", "")
			.trim().toLowerCase(Locale.ENGLISH);
	}
}

package com.itemsource;

public enum RankingPreference
{
	BALANCED,
	FASTEST,
	CHEAPEST,
	SAFEST
}

package com.itemsource;

enum SourceCategory
{
	SHOPS("Shops"), MONSTER_DROPS("Monster drops"),
	CRAFTING_AND_SKILLS("Crafting & skills"), GROUND_SPAWNS("Ground spawns"),
	REWARDS("Rewards");

	private final String displayName;
	SourceCategory(String displayName) { this.displayName = displayName; }
	String getDisplayName() { return displayName; }
}

package com.itemsource;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;

final class SourceEntry
{
	private final String title;
	private final String detail;
	private final String requiredSkill;
	private final int requiredLevel;
	private final Map<String, Integer> requiredLevels;
	private final int requiredQuestPoints;
	private final List<String> requiredQuests;
	private final String requiredSlayerTask;
	private final String availabilityIssue;
	private final boolean requirementDataChecked;
	private final Map<String, Integer> recommendedLevels;
	private final boolean wildernessRisk;
	private final Integer mapX;
	private final Integer mapY;

	SourceEntry(String title, String detail)
	{
		this(title, detail, null, 0);
	}

	SourceEntry(String title, String detail, String requiredSkill, int requiredLevel)
	{
		this(title, detail, requiredSkill, requiredLevel, Collections.emptyList());
	}

	SourceEntry(String title, String detail, String requiredSkill, int requiredLevel,
		List<String> requiredQuests)
	{
		this(title, detail, requiredSkill, requiredLevel, requiredQuests, null, null);
	}

	SourceEntry(String title, String detail, String requiredSkill, int requiredLevel,
		List<String> requiredQuests, String requiredSlayerTask, String availabilityIssue)
	{
		this.title = title;
		this.detail = detail;
		this.requiredSkill = requiredSkill;
		this.requiredLevel = requiredLevel;
		this.requiredLevels = Collections.unmodifiableMap(requirementMap(requiredSkill, requiredLevel));
		this.requiredQuestPoints = 0;
		this.requiredQuests = Collections.unmodifiableList(new ArrayList<>(requiredQuests));
		this.requiredSlayerTask = requiredSlayerTask;
		this.availabilityIssue = availabilityIssue;
		this.requirementDataChecked = requiredLevel > 0 || !requiredQuests.isEmpty();
		this.recommendedLevels = Collections.emptyMap();
		this.wildernessRisk = false;
		this.mapX = null;
		this.mapY = null;
	}

	private SourceEntry(String title, String detail, String requiredSkill, int requiredLevel,
		List<String> requiredQuests, String requiredSlayerTask, String availabilityIssue,
		boolean requirementDataChecked)
	{
		this(title, detail, requiredSkill, requiredLevel, requiredQuests, requiredSlayerTask,
			availabilityIssue, requirementDataChecked, Collections.emptyMap(), false, null, null);
	}

	private SourceEntry(String title, String detail, String requiredSkill, int requiredLevel,
		List<String> requiredQuests, String requiredSlayerTask, String availabilityIssue,
		boolean requirementDataChecked, Map<String, Integer> recommendedLevels)
	{
		this(title, detail, requiredSkill, requiredLevel, requiredQuests, requiredSlayerTask,
			availabilityIssue, requirementDataChecked, recommendedLevels, false, null, null);
	}

	private SourceEntry(String title, String detail, String requiredSkill, int requiredLevel,
		List<String> requiredQuests, String requiredSlayerTask, String availabilityIssue,
		boolean requirementDataChecked, Map<String, Integer> recommendedLevels,
		boolean wildernessRisk, Integer mapX, Integer mapY)
	{
		this(title, detail, requiredSkill, requiredLevel, requirementMap(requiredSkill, requiredLevel), 0,
			requiredQuests, requiredSlayerTask, availabilityIssue, requirementDataChecked,
			recommendedLevels, wildernessRisk, mapX, mapY);
	}

	private SourceEntry(String title, String detail, String requiredSkill, int requiredLevel,
		Map<String, Integer> requiredLevels, int requiredQuestPoints,
		List<String> requiredQuests, String requiredSlayerTask, String availabilityIssue,
		boolean requirementDataChecked, Map<String, Integer> recommendedLevels,
		boolean wildernessRisk, Integer mapX, Integer mapY)
	{
		this.title = title;
		this.detail = detail;
		this.requiredSkill = requiredSkill;
		this.requiredLevel = requiredLevel;
		this.requiredLevels = Collections.unmodifiableMap(new LinkedHashMap<>(requiredLevels));
		this.requiredQuestPoints = requiredQuestPoints;
		this.requiredQuests = Collections.unmodifiableList(new ArrayList<>(requiredQuests));
		this.requiredSlayerTask = requiredSlayerTask;
		this.availabilityIssue = availabilityIssue;
		this.requirementDataChecked = requirementDataChecked;
		this.recommendedLevels = Collections.unmodifiableMap(new LinkedHashMap<>(recommendedLevels));
		this.wildernessRisk = wildernessRisk;
		this.mapX = mapX;
		this.mapY = mapY;
	}

	String getTitle() { return title; }
	String getDetail() { return detail; }
	String getRequiredSkill() { return requiredSkill; }
	int getRequiredLevel() { return requiredLevel; }
	Map<String, Integer> getRequiredLevels() { return requiredLevels; }
	int getRequiredQuestPoints() { return requiredQuestPoints; }
	List<String> getRequiredQuests() { return requiredQuests; }
	String getRequiredSlayerTask() { return requiredSlayerTask; }
	String getAvailabilityIssue() { return availabilityIssue; }
	boolean isRequirementDataChecked() { return requirementDataChecked; }
	Map<String, Integer> getRecommendedLevels() { return recommendedLevels; }
	boolean hasWildernessRisk() { return wildernessRisk; }
	Integer getMapX() { return mapX; }
	Integer getMapY() { return mapY; }

	SourceEntry withRequirement(SourceRequirement requirement)
	{
		List<String> quests = new ArrayList<>(requiredQuests);
		for (String quest : requirement.getQuests()) if (!quests.contains(quest)) quests.add(quest);
		Map<String, Integer> levels = new LinkedHashMap<>(requiredLevels);
		requirement.getRequiredLevels().forEach((skillName, skillLevel) ->
			levels.merge(skillName, skillLevel, Math::max));
		String skill = levels.isEmpty() ? null : levels.keySet().iterator().next();
		int level = levels.isEmpty() ? 0 : levels.values().iterator().next();
		return new SourceEntry(title, detail, skill, level, levels,
			Math.max(requiredQuestPoints, requirement.getQuestPoints()), quests,
			requirement.getSlayerTask(), availabilityIssue, true,
			requirement.getRecommendedLevels(), requirement.hasWildernessRisk(),
			requirement.getMapX(), requirement.getMapY());
	}

	@Override public boolean equals(Object other)
	{
		if (this == other) return true;
		if (!(other instanceof SourceEntry)) return false;
		SourceEntry entry = (SourceEntry) other;
		return title.equals(entry.title) && detail.equals(entry.detail)
			&& requiredLevels.equals(entry.requiredLevels)
			&& requiredQuestPoints == entry.requiredQuestPoints
			&& requiredQuests.equals(entry.requiredQuests)
			&& Objects.equals(requiredSlayerTask, entry.requiredSlayerTask)
			&& Objects.equals(availabilityIssue, entry.availabilityIssue)
			&& requirementDataChecked == entry.requirementDataChecked
			&& recommendedLevels.equals(entry.recommendedLevels)
			&& wildernessRisk == entry.wildernessRisk
			&& Objects.equals(mapX, entry.mapX) && Objects.equals(mapY, entry.mapY);
	}

	@Override public int hashCode()
	{
		return Objects.hash(title, detail, requiredLevels, requiredQuestPoints, requiredQuests, requiredSlayerTask,
			availabilityIssue, requirementDataChecked, recommendedLevels, wildernessRisk, mapX, mapY);
	}

	private static Map<String, Integer> requirementMap(String skill, int level)
	{
		Map<String, Integer> levels = new LinkedHashMap<>();
		if (skill != null && level > 0) levels.put(skill, level);
		return levels;
	}
}

package com.itemsource;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.LinkedHashMap;
import java.util.Map;

final class SourceRequirement
{
	private final Map<String, Integer> requiredLevels;
	private final int questPoints;
	private final List<String> quests;
	private final String slayerTask;
	private final Map<String, Integer> recommendedLevels;
	private final boolean wildernessRisk;
	private final String locationPage;
	private final Integer mapX;
	private final Integer mapY;

	SourceRequirement(String skill, int level, List<String> quests, String slayerTask)
	{
		this(skill, level, quests, slayerTask, Collections.emptyMap());
	}

	SourceRequirement(String skill, int level, List<String> quests, String slayerTask,
		Map<String, Integer> recommendedLevels)
	{
		this(skill, level, quests, slayerTask, recommendedLevels, false);
	}

	SourceRequirement(String skill, int level, List<String> quests, String slayerTask,
		Map<String, Integer> recommendedLevels, boolean wildernessRisk)
	{
		this(skill, level, quests, slayerTask, recommendedLevels, wildernessRisk, null);
	}

	SourceRequirement(String skill, int level, List<String> quests, String slayerTask,
		Map<String, Integer> recommendedLevels, boolean wildernessRisk, String locationPage)
	{
		this(skill, level, quests, slayerTask, recommendedLevels, wildernessRisk, locationPage, null, null);
	}

	SourceRequirement(String skill, int level, List<String> quests, String slayerTask,
		Map<String, Integer> recommendedLevels, boolean wildernessRisk, String locationPage,
		Integer mapX, Integer mapY)
	{
		this(requirementMap(skill, level), 0, quests, slayerTask, recommendedLevels,
			wildernessRisk, locationPage, mapX, mapY);
	}

	SourceRequirement(Map<String, Integer> requiredLevels, int questPoints,
		List<String> quests, String slayerTask, Map<String, Integer> recommendedLevels,
		boolean wildernessRisk, String locationPage, Integer mapX, Integer mapY)
	{
		this.requiredLevels = Collections.unmodifiableMap(new LinkedHashMap<>(requiredLevels));
		this.questPoints = questPoints;
		this.quests = Collections.unmodifiableList(new ArrayList<>(quests));
		this.slayerTask = slayerTask;
		this.recommendedLevels = Collections.unmodifiableMap(new LinkedHashMap<>(recommendedLevels));
		this.wildernessRisk = wildernessRisk;
		this.locationPage = locationPage;
		this.mapX = mapX;
		this.mapY = mapY;
	}

	String getSkill() { return requiredLevels.isEmpty() ? null : requiredLevels.keySet().iterator().next(); }
	int getLevel() { return requiredLevels.isEmpty() ? 0 : requiredLevels.values().iterator().next(); }
	Map<String, Integer> getRequiredLevels() { return requiredLevels; }
	int getQuestPoints() { return questPoints; }
	List<String> getQuests() { return quests; }
	String getSlayerTask() { return slayerTask; }
	Map<String, Integer> getRecommendedLevels() { return recommendedLevels; }
	boolean hasWildernessRisk() { return wildernessRisk; }
	String getLocationPage() { return locationPage; }
	Integer getMapX() { return mapX; }
	Integer getMapY() { return mapY; }

	SourceRequirement merge(SourceRequirement other)
	{
		List<String> combinedQuests = new ArrayList<>(quests);
		for (String quest : other.quests) if (!combinedQuests.contains(quest)) combinedQuests.add(quest);
		Map<String, Integer> combinedLevels = new LinkedHashMap<>(recommendedLevels);
		other.recommendedLevels.forEach((skillName, skillLevel) ->
			combinedLevels.merge(skillName, skillLevel, Math::max));
		Map<String, Integer> combinedRequired = new LinkedHashMap<>(requiredLevels);
		other.requiredLevels.forEach((skillName, skillLevel) ->
			combinedRequired.merge(skillName, skillLevel, Math::max));
		return new SourceRequirement(combinedRequired, Math.max(questPoints, other.questPoints), combinedQuests,
			slayerTask != null ? slayerTask : other.slayerTask, combinedLevels,
			wildernessRisk || other.wildernessRisk,
			locationPage != null ? locationPage : other.locationPage,
			mapX != null ? mapX : other.mapX, mapY != null ? mapY : other.mapY);
	}

	private static Map<String, Integer> requirementMap(String skill, int level)
	{
		Map<String, Integer> levels = new LinkedHashMap<>();
		if (skill != null && level > 0) levels.put(skill, level);
		return levels;
	}
}

package com.itemsource;

import java.util.ArrayList;
import java.util.List;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Quest;

final class SourceRequirementParser
{
	private static final Pattern SLAYER_LEVEL = Pattern.compile("(?im)^\\|\\s*slaylvl\\s*=\\s*(\\d+)");
	private static final Pattern SLAYER_TASK = Pattern.compile(
		"(?is)(?:only|must).{0,45}?(?:attacked|killed|fought).{0,45}?on (?:an? )?\\[?\\[?([a-z][a-z '\\-]+?)(?:\\]\\])? task");
	private static final int REQUIREMENT_CONTEXT = 100;
	private static final Pattern RECOMMENDED_SKILL = Pattern.compile(
		"(?i)\\{\\{SCP\\|(Attack|Strength|Defence|Ranged|Magic|Prayer|Hitpoints)\\|(\\d+)");
	private static final Pattern LOCATION_PAGE = Pattern.compile(
		"(?im)^\\|\\s*location\\s*=.*?\\[\\[([^]|#]+)");
	private static final Pattern LOCATION_SENTENCE = Pattern.compile(
		"(?is)(?:found|located|cyclopes).{0,90}?\\b(?:in|at)\\s+(?:the\\s+)?\\[\\[([^]|#]+)");
	private static final Pattern COMBINED_ATTACK_STRENGTH = Pattern.compile(
		"(?is)combined\\s+\\[\\[Attack\\]\\]\\s+and\\s+\\[\\[Strength\\]\\]\\s+level.{0,30}?(\\d+)");
	private static final Pattern REQUIREMENT_FIELD = Pattern.compile(
		"(?im)^\\|\\s*requirements?\\s*=\\s*([^\\r\\n]*)");
	private static final Pattern ACCESS_SKILL = Pattern.compile(
		"(?i)\\{\\{SCP\\|(?!Quest\\b)([A-Za-z ]+)\\|(\\d+)");
	private static final Pattern QUEST_POINTS = Pattern.compile(
		"(?i)(\\d+)\\s*\\[\\[Quest points?\\]\\]");
	private static final Pattern MAP_X = Pattern.compile("(?i)\\|\\s*x\\s*=\\s*(\\d+)");
	private static final Pattern MAP_Y = Pattern.compile("(?i)\\|\\s*y\\s*=\\s*(\\d+)");

	SourceRequirement parse(String wikitext)
	{
		String requirementText = wikitext.substring(0, Math.min(wikitext.length(), 6000));
		Matcher levelMatcher = SLAYER_LEVEL.matcher(requirementText);
		int slayerLevel = levelMatcher.find() ? Integer.parseInt(levelMatcher.group(1)) : 0;
		List<String> quests = new ArrayList<>();
		for (Quest quest : Quest.values())
		{
			String link = "[[" + quest.getName();
			int from = 0;
			while ((from = indexOfIgnoreCase(requirementText, link, from)) >= 0)
			{
				int afterLink = from + link.length();
				if (afterLink < requirementText.length() && requirementText.charAt(afterLink) != ']'
					&& requirementText.charAt(afterLink) != '|' && requirementText.charAt(afterLink) != '#')
				{
					from = afterLink;
					continue;
				}
				int start = Math.max(0, from - REQUIREMENT_CONTEXT);
				int end = Math.min(requirementText.length(), from + link.length() + REQUIREMENT_CONTEXT);
				String context = requirementText.substring(start, end).toLowerCase(Locale.ENGLISH);
				if (isRequirementContext(context))
				{
					quests.add(quest.getName());
					break;
				}
				from += link.length();
			}
		}

		Matcher taskMatcher = SLAYER_TASK.matcher(requirementText);
		String task = taskMatcher.find() ? cleanTask(taskMatcher.group(1)) : null;
		if ("slayer".equalsIgnoreCase(task)) task = null;
		boolean wilderness = Pattern.compile("(?im)^\\|\\s*location\\s*=.*wilderness")
			.matcher(requirementText).find() || requirementText.toLowerCase(Locale.ENGLISH).contains("wilderness boss");
		Matcher locationMatcher = LOCATION_PAGE.matcher(requirementText);
		String locationPage = locationMatcher.find() ? locationMatcher.group(1).trim() : null;
		if (locationPage == null)
		{
			locationMatcher = LOCATION_SENTENCE.matcher(requirementText);
			if (locationMatcher.find()) locationPage = locationMatcher.group(1).trim();
		}
		Matcher combinedMatcher = COMBINED_ATTACK_STRENGTH.matcher(requirementText);
		int combinedLevel = combinedMatcher.find() ? Integer.parseInt(combinedMatcher.group(1)) : 0;
		Map<String, Integer> requiredLevels = new LinkedHashMap<>();
		if (slayerLevel > 0) requiredLevels.put("Slayer", slayerLevel);
		if (combinedLevel > 0) requiredLevels.put("Attack + Strength", combinedLevel);
		int questPoints = 0;
		Matcher requirementFieldMatcher = REQUIREMENT_FIELD.matcher(requirementText);
		while (requirementFieldMatcher.find())
		{
			String field = requirementFieldMatcher.group(1);
			Matcher accessSkillMatcher = ACCESS_SKILL.matcher(field);
			while (accessSkillMatcher.find())
			{
				String accessSkill = accessSkillMatcher.group(1).trim();
				int accessLevel = Integer.parseInt(accessSkillMatcher.group(2));
				requiredLevels.merge(accessSkill, accessLevel, Math::max);
			}
			Matcher questPointMatcher = QUEST_POINTS.matcher(field);
			if (questPointMatcher.find()) questPoints = Math.max(questPoints,
				Integer.parseInt(questPointMatcher.group(1)));
		}
		Matcher xMatcher = MAP_X.matcher(requirementText);
		Matcher yMatcher = MAP_Y.matcher(requirementText);
		Integer mapX = xMatcher.find() ? Integer.parseInt(xMatcher.group(1)) : null;
		Integer mapY = yMatcher.find() ? Integer.parseInt(yMatcher.group(1)) : null;
		return new SourceRequirement(requiredLevels, questPoints, quests, task,
			new LinkedHashMap<>(), wilderness, locationPage, mapX, mapY);
	}

	SourceRequirement parseStrategy(String wikitext)
	{
		String section = recommendationSection(wikitext);
		Map<String, Integer> levels = new LinkedHashMap<>();
		Matcher matcher = RECOMMENDED_SKILL.matcher(section);
		while (matcher.find())
		{
			String skill = matcher.group(1);
			int level = Integer.parseInt(matcher.group(2));
			levels.merge(skill, level, Math::max);
		}
		boolean wilderness = section.toLowerCase(Locale.ENGLISH).contains("wilderness");
		return new SourceRequirement(null, 0, new ArrayList<>(), null, levels, wilderness);
	}

	private static String recommendationSection(String text)
	{
		Matcher start = Pattern.compile("(?im)^={2,3}(Suggested skills|Recommendations)={2,3}\\s*$").matcher(text);
		if (!start.find()) return "";
		int headingLevel = start.group().startsWith("===") ? 3 : 2;
		Matcher next = Pattern.compile("(?m)^={2," + headingLevel + "}[^=].*?={2," + headingLevel + "}\\s*$")
			.matcher(text);
		next.region(start.end(), text.length());
		int end = next.find() ? next.start() : text.length();
		return text.substring(start.end(), end);
	}

	private static boolean isRequirementContext(String context)
	{
		return context.contains("requires completion") || context.contains("require completion")
			|| context.contains("completed") || context.contains("completion of")
			|| context.contains("must complete") || context.contains("after completing")
			|| context.contains("not yet complete") || context.contains("quest is completed")
			|| context.matches("(?s).*\\|\\s*requirements?\\s*=.*")
			|| context.matches("(?s).*\\|\\s*quest\\s*=.*");
	}

	private static int indexOfIgnoreCase(String text, String wanted, int from)
	{
		return text.toLowerCase(Locale.ENGLISH).indexOf(wanted.toLowerCase(Locale.ENGLISH), from);
	}

	private static String cleanTask(String value)
	{
		return value.replaceAll("(?is)<[^>]+>", " ").replaceAll("\\s+", " ").trim();
	}
}

package com.itemsource;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class ItemSourceParserTest
{
	@Test public void formatsDropsShopsAndSpawnsWithoutUnrelatedColumns()
	{
		String html = "<h2>Item sources</h2><table>"
			+ "<tr><th>Source</th><th>Level</th><th>Quantity</th><th>Rarity</th></tr>"
			+ "<tr><td>Fire giant</td><td>86; 104; 109</td><td>1</td><td>1/128</td></tr></table>"
			+ "<h3>Shop locations</h3><table>"
			+ "<tr><th>Seller</th><th>Location</th><th>Number in stock</th><th>Price sold at</th></tr>"
			+ "<tr><td>Scavvo</td><td>Champions' Guild</td><td>1</td><td>32,000</td></tr></table>"
			+ "<h2>Spawn locations</h2><table>"
			+ "<tr><th>Location</th><th>Members</th><th>Spawns</th><th>Map</th></tr>"
			+ "<tr><td>Varrock Sewers</td><td></td><td>2</td><td>Show map</td></tr></table>";
		ItemSourceResult result = new ItemSourceParser().parse("Rune scimitar", html);

		SourceEntry drop = result.getSources().get(SourceCategory.MONSTER_DROPS).get(0);
